  public static string GetFullnameByID(int npcID)
  {
    for (int index = 0; index < Main.maxNPCs; ++index)
    {
      if (Main.npc[index].active && Main.npc[index].type == npcID)
        return Main.npc[index].FullName;
    }
    return Lang.GetNPCNameValue(npcID);
  }

