  }

  public int GetAttackDamage_ScaledByDifficulty(float normalDamage)
  {
    return (int) ((double) normalDamage * (double) GameDifficultyData.EnemyDamageMultiplier.Sample(this.difficulty));
  }

  public int GetAttackDamage_CappedAtMaster(float normalDamage)
  {
    float num = Math.Min(this.difficulty, GameDifficultyLevel.Master);
    return (int) ((double) normalDamage * (double) GameDifficultyData.EnemyDamageMultiplier.Sample(num));
  }

  public int GetAttackDamage_LerpBetweenFinalValues(float normalDamage, float expertDamage)
  {
