  {
    return (int) Utils.MultiLerp(Utils.GetLerpValue(GameDifficultyLevel.Classic, GameDifficultyLevel.Master, this.difficulty, true), normalDamage, expertDamage, masterDamage);
  }

  public int GetAttackDamage_ForTownNPC(float normalDamage)
