  public int GetBossHeadTextureIndex()
  {
    int headTextureIndex = NPCID.Sets.BossHeadTextures[this.type];
    switch (this.type)
    {
      case 4:
        if ((double) this.ai[0] >= 2.0)
        {
          headTextureIndex = 1;
          break;
        }
        break;
      case 125:
        if ((double) this.ai[0] >= 3.0)
        {
          headTextureIndex = 16 /*0x10*/;
          break;
        }
        break;
      case 126:
        if ((double) this.ai[0] >= 3.0)
        {
          headTextureIndex = 21;
          break;
        }
        break;
      case 262:
        if (this.life <= this.lifeMax / 2)
        {
          headTextureIndex = 12;
          break;
        }
        break;
      case 266:
        if ((double) this.ai[0] < 0.0 || (double) this.localAI[2] > 0.0)
        {
          headTextureIndex = -1;
          break;
        }
        break;
      case 439:
        if ((double) this.ai[0] == 5.0 && this.alpha == (int) byte.MaxValue)
        {
          headTextureIndex = -1;
          break;
        }
        break;
      case 440:
        if ((double) this.ai[0] != 5.0 || this.alpha == (int) byte.MaxValue)
        {
          headTextureIndex = -1;
          break;
        }
        break;
    }
    return headTextureIndex;
  }

