  {
    float bossHeadRotation = 0.0f;
    switch (this.type)
    {
      case 35:
      case (int) sbyte.MaxValue:
        if ((double) this.ai[1] == 1.0 || (double) this.ai[1] == 2.0)
        {
          bossHeadRotation = this.rotation;
          break;
        }
        break;
      case 68:
      case 262:
        bossHeadRotation = this.rotation;
        break;
      case 345:
        if ((double) this.ai[0] == 2.0)
        {
          bossHeadRotation = this.rotation;
          break;
        }
        break;
    }
    return bossHeadRotation;
  }

