  public void SetDefaults_ForNetId(int Type, NPCSpawnParams spawnparams, float scaleOverride)
  {
    this.SetDefaults(Type, spawnparams.WithScale(scaleOverride));
  }

  public void ResetForNewNPC()
  {
    this.netOffset = Vector2.Zero;
    this.netStream = 0;
    this.netSpam = 0;
    Array.Clear((Array) this.playerNetSyncState, 0, this.playerNetSyncState.Length);
    this.velocity = Vector2.Zero;
    this.direction = 0;
    this.oldDirection = 0;
    this.spriteDirection = -1;
    this.wet = false;
    this.lavaWet = false;
    this.honeyWet = false;
    this.shimmerWet = false;
    this.SpawnedFromStatue = false;
    this.extraValue = 0;
    this.shimmerTransparency = 0.0f;
    this.lookForHomeTimeout = 0;
    Array.Clear((Array) this.buffTime, 0, this.buffTime.Length);
    Array.Clear((Array) this.buffType, 0, this.buffType.Length);
    Array.Clear((Array) this.playerInteraction, 0, this.playerInteraction.Length);
    if (this.whoAmI >= Main.maxNPCs)
      return;
    PortalHelper.ResetNPCSlotData(this.whoAmI);
    Projectile.ResetNPCSlotData(this.whoAmI);
    Player.ResetNPCSlotData(this.whoAmI);
  }

