  private void getTenthAnniversaryAdjustments()
  {
    float scale = this.scale;
    float num = 0.5f;
    switch (this.type)
    {
      case 4:
        this.scale *= num;
        break;
      case 13:
      case 14:
      case 15:
        this.scale *= num;
        break;
      case 35:
      case 36:
        this.scale *= num;
        break;
      case 113:
      case 114:
      case 115:
      case 116:
        this.scale *= num;
        break;
      case 125:
      case 126:
        this.scale *= num;
        break;
      case (int) sbyte.MaxValue:
      case 128 /*0x80*/:
      case 129:
      case 130:
      case 131:
        this.scale *= num;
        break;
      case 134:
      case 135:
      case 136:
      case 139:
        this.scale *= num;
        break;
      case 222:
        this.scale *= num;
        break;
      case 266:
      case 267:
        this.scale *= num;
        break;
      case 370:
        this.scale *= num;
        break;
      case 422:
      case 493:
      case 507:
      case 517:
        this.scale *= num;
        break;
      case 636:
        this.scale *= num;
        break;
    }
    if (this.IsABestiaryIconDummy)
    {
      this.scale = scale;
    }
    else
    {
      this.width = (int) ((double) this.width * (double) this.scale);
      this.height = (int) ((double) this.height * (double) this.scale);
    }
  }

  private void getZenithSeedAdjustmentsBeforeEverything()
  {
    switch (this.type)
    {
      case 125:
      case 126:
      case (int) sbyte.MaxValue:
      case 128 /*0x80*/:
      case 129:
      case 130:
      case 131:
      case 139:
        this.lifeMax = (int) ((double) this.lifeMax * 0.800000011920929);
        break;
    }
  }

  private void getGoodAdjustments()
  {
    float scale = this.scale;
    if (this.type == 13)
    {
      this.scale *= 1.35f;
      this.defense += 2;
    }
    else if (this.type == 14)
    {
      this.scale *= 1.4f;
      this.defense += 2;
    }
    else if (this.type == 15)
    {
      this.scale *= 1.4f;
      this.defense += 2;
    }
    else if (this.type == 40 || this.type == 39 || this.type == 41)
    {
      this.lifeMax += 100;
      this.defense += 2;
      this.damage += 4;
      this.scale = 1.1f;
      if (Main.remixWorld)
      {
        this.lifeMax += 50;
        this.scale *= 1.2f;
        this.defense += 4;
      }
    }
    else if (this.type == 35)
      this.scale *= 1.25f;
    else if (this.type == 36)
      this.scale *= 1.15f;
    else if (this.type == 113)
    {
      this.scale *= 0.65f;
      this.lifeMax = (int) ((double) this.lifeMax * 1.5);
      this.defense += 3;
    }
    else if (this.type == 114)
    {
      this.scale *= 0.65f;
      this.lifeMax = (int) ((double) this.lifeMax * 1.5);
      this.defense += 3;
    }
    else if (this.type == 115)
      this.scale *= 1.4f;
    else if (this.type == 116)
      this.scale *= 1.4f;
    else if (this.type == 118)
    {
      this.damage += 10;
      this.defense += 14;
      this.lifeMax *= 3;
    }
    else if (this.type == 222)
      this.scale *= 1.2f;
    else if (this.type == 245)
    {
      this.canDisplayBuffs = false;
      this.scale *= 0.5f;
    }
    else if (this.type == 246)
    {
      this.canDisplayBuffs = false;
      this.scale *= 0.5f;
    }
    else if (this.type == 247 || this.type == 248)
    {
      this.canDisplayBuffs = false;
      this.scale *= 0.5f;
    }
    else if (this.type == 249)
      this.scale *= 0.5f;
    else if (this.type == 262)
      this.scale *= 1.3f;
    else if (this.type == 266)
    {
      this.defense = (int) ((double) this.defense * 1.5);
      this.damage = (int) ((double) this.damage * 1.2);
      this.scale *= 1.1f;
    }
    else if (this.type == 125)
      this.scale *= 0.8f;
    else if (this.type == 126)
      this.scale *= 0.8f;
    else if (this.type == (int) sbyte.MaxValue)
      this.scale *= 1.1f;
    else if (this.type == 128 /*0x80*/)
      this.scale *= 1.1f;
    else if (this.type == 129)
      this.scale *= 1.1f;
    else if (this.type == 130)
      this.scale *= 1.1f;
    else if (this.type == 131)
      this.scale *= 1.1f;
    else if (this.type == 134)
      this.scale *= 1.3f;
    else if (this.type == 135)
      this.scale *= 1.3f;
    else if (this.type == 136)
    {
      this.scale *= 1.3f;
    }
    else
    {
      if (this.type != 139)
        return;
      this.scale *= 1.6f;
    }
    if (this.IsABestiaryIconDummy)
    {
      this.scale = scale;
    }
    else
    {
      this.width = (int) ((double) this.width * (double) this.scale);
      this.height = (int) ((double) this.height * (double) this.scale);
    }
  }

  private void LazySetLiquidMovementDD2()
