  public void ScaleStats(int? activePlayersCount, float? strengthOverride)
  {
    if (!NPCID.Sets.NeedsExpertScaling[this.type] && (this.lifeMax <= 5 || this.damage == 0 || this.friendly || this.townNPC))
      return;
    this.difficulty = strengthOverride.HasValue ? strengthOverride.Value : Main.Difficulty;
    if ((double) this.difficulty >= (double) GameDifficultyLevel.Expert && Main.hardMode)
      this.ScaleStats_ForExpertHardmode();
    this.ScaleStats_ByDifficulty();
    if ((double) this.difficulty >= (double) GameDifficultyLevel.Expert)
      this.ScaleStats_ByPlayerCount(activePlayersCount.HasValue ? activePlayersCount.Value : NPC.GetActivePlayerCount());
    if ((this.type < 0 ? 0 : (NPCID.Sets.ProjectileNPC[this.type] ? 1 : 0)) == 0 && this.lifeMax < 6)
      this.lifeMax = 6;
    this.life = this.lifeMax;
    this.defDamage = this.damage;
    this.defDefense = this.defense;
    this.defLifeMax = this.lifeMax;
  }

  public void ScaleStats_ByDifficulty()
  {
    if ((this.type < 0 ? 0 : (NPCID.Sets.ProjectileNPC[this.type] ? 1 : 0)) == 0)
    {
      this.lifeMax = (int) ((double) this.lifeMax * (double) GameDifficultyData.EnemyMaxLifeMultiplier.Sample(this.difficulty));
      this.value = (float) (int) ((double) this.value * (double) GameDifficultyData.EnemyMoneyDropMultiplier.Sample(this.difficulty));
    }
    this.damage = this.GetAttackDamage_ScaledByDifficulty((float) this.damage);
    this.knockBackResist = this.GetKnockbackMultiplier_ScaledByDifficulty(this.knockBackResist);
    this.ScaleStats_ByDifficulty_Tweaks();
  }

