        float num = Vector2.DistanceSquared(center, player.Center);
        if ((double) num < (double) d)
        {
          d = num;
          closestPlayer = index;
        }
      }
    }
    if (closestPlayer < 0)
    {
      for (int index = 0; index < (int) byte.MaxValue; ++index)
      {
        Player player = Main.player[index];
        if (player.active)
        {
