  public void NPCLoot()
  {
    if (Main.netMode == 1 || this.type >= (int) NPCID.Count || (Main.getGoodWorld || !Main.isThereAWorldSurface) && !NPC.downedBoss3 && !Main.onlyShimmerOceanWorlds && (this.type == 31 /*0x1F*/ || this.type == 294 || this.type == 296 || this.type == 295 || this.type == 32 /*0x20*/ || this.type == 34 || this.type == 71 || this.type == 693 || this.type == 694) || this.type == 32 /*0x20*/ && (double) this.localAI[3] == 1.0)
      return;
    Player closestPlayer = Main.player[(int) Player.FindClosest(this.position, this.width, this.height)];
    if (true)
    {
      this.CountKillForAchievements();
      if (this.GetWereThereAnyInteractions())
      {
        if (this.IsNPCValidForBestiaryKillCredit())
          Main.BestiaryTracker.Kills.RegisterKill(this);
        this.CountKillForBannersAndDropThem();
      }
    }
    if (this.SpawnedFromStatue && NPCID.Sets.NoEarlymodeLootWhenSpawnedFromStatue[this.type] && !Main.hardMode || this.SpawnedFromStatue && (double) NPCID.Sets.StatueSpawnedDropRarity[this.type] != -1.0 && ((double) Main.rand.NextFloat() >= (double) NPCID.Sets.StatueSpawnedDropRarity[this.type] || !this.AnyInteractions()))
      return;
    bool flag1 = NPC.downedMechBoss1 && NPC.downedMechBoss2 && NPC.downedMechBoss3;
    this.DoDeathEvents_BeforeLoot(closestPlayer);
    this.NPCLoot_DropItems(closestPlayer);
    this.DoDeathEvents(closestPlayer);
    if (SpecialSeedFeatures.Mechdusa)
    {
      switch (this.type)
