    for (int index1 = num1 - num3; index1 <= num1 + num3; ++index1)
    {
      for (int index2 = num2 - num3; index2 <= num2 + num3; ++index2)
      {
        if ((index1 == num1 - num3 || index1 == num1 + num3 || index2 == num2 - num3 || index2 == num2 + num3) && !Main.tile[index1, index2].active())
