  public static int NewNPC(
    IEntitySource source,
    int X,
    int Y,
    int Type,
    int Start = 0,
    float ai0 = 0.0f,
    float ai1 = 0.0f,
    float ai2 = 0.0f,
    float ai3 = 0.0f,
    int Target = 255 /*0xFF*/)
  {
    if (Main.getGoodWorld && Main.rand.Next(3) != 0)
    {
      if (Type == 46)
        Type = 614;
      if (Type == 62)
        Type = 66;
    }
    int availableNpcSlot = NPC.GetAvailableNPCSlot(Type, Start);
    if (availableNpcSlot < 0)
      return Main.maxNPCs;
    NPC.spawnSlotProtected[availableNpcSlot] = 2;
    NPC npc = new NPC();
    Main.npc[availableNpcSlot] = npc;
    npc.whoAmI = availableNpcSlot;
    npc.ResetForNewNPC();
    npc.SetDefaults(Type);
    NPC.GiveTownUniqueDataToNPCsThatNeedIt(Type, availableNpcSlot);
    npc.Bottom = new Vector2((float) X, (float) Y);
    npc.active = true;
    npc.timeLeft = (int) ((double) NPC.activeTime * 1.25);
    if (!npc.noTileCollide)
      npc.wet = Collision.WetCollision(npc.position, npc.width, npc.height);
    npc.ai[0] = ai0;
    npc.ai[1] = ai1;
    npc.ai[2] = ai2;
    npc.ai[3] = ai3;
    npc.target = Target;
    if (Main.netMode == 2)
      npc.spawnNeedsSyncing = true;
    if (Type == 50)
    {
      switch (Main.netMode)
      {
        case 0:
          Main.NewText(Language.GetTextValue("Announcement.HasAwoken", (object) npc.TypeName), (byte) 175, (byte) 75);
          break;
        case 2:
          ChatHelper.BroadcastChatMessage(NetworkText.FromKey("Announcement.HasAwoken", (object) npc.GetTypeNetName()), new Color(175, 75, (int) byte.MaxValue));
          break;
      }
    }
    return availableNpcSlot;
  }

  private static int GetAvailableNPCSlot(int Type, int startIndex)
  {
    Type = NPCID.FromNetId(Type);
    int num1 = NPCID.Sets.SearchSpawnSlotsInReverse[Type] ? 1 : 0;
    if (startIndex == 0 && NPCID.Sets.CannotSpawnInSlot0[Type])
      startIndex = 1;
    int maxNpCs = Main.maxNPCs;
    int num2 = 1;
    if (num1 != 0)
    {
      --maxNpCs;
      Utils.Swap<int>(ref startIndex, ref maxNpCs);
      num2 = -1;
    }
    for (int slot = startIndex; slot != maxNpCs; slot += num2)
    {
      if (!NPC.IsSpawnSlotInUse(slot))
        return slot;
    }
    for (int availableNpcSlot = startIndex; availableNpcSlot != maxNpCs; availableNpcSlot += num2)
    {
      if (Main.npc[availableNpcSlot].CanBeReplacedByOtherNPCs)
        return availableNpcSlot;
    }
    return -1;
  }

  private static bool IsSpawnSlotInUse(int slot)
  {
    return Main.npc[slot].active || NPC.spawnSlotProtected[slot] > 0;
  }

  private static void GiveTownUniqueDataToNPCsThatNeedIt(int Type, int nextNPC)
  {
    NPC npc = Main.npc[nextNPC];
    if (!npc.isLikeATownNPC)
      return;
    npc.GivenName = NPC.getNewNPCName(Type);
    ITownNPCProfile profile;
    if (TownNPCProfiles.Instance.GetProfile(Type, out profile))
    {
      npc.townNpcVariationIndex = profile.RollVariation();
      npc.GivenName = profile.GetNameForVariant(npc);
    }
    if (NPC.ShimmeredTownNPCs[Type])
      npc.townNpcVariationIndex = 1;
    npc.needsUniqueInfoUpdate = true;
  }

