          npc.ai[2] = 0.0f;
          npc.localAI[3] = 0.0f;
          npc.direction = hitDirection;
          npc.netUpdate = true;
        }
      }
      this.ai[0] = 1f;
      this.ai[1] = (float) (300 + Main.rand.Next(300));
      this.ai[2] = 0.0f;
      this.localAI[3] = 0.0f;
      this.direction = hitDirection;
      this.netUpdate = true;
    }
    if (Main.netMode != 1 && this.aiStyle == 87 && (double) this.ai[0] == 0.0)
    {
      this.ai[0] = 1f;
      this.ai[1] = 0.0f;
