      return;
    int num = 2;
    if ((oldAltTexture != 0 || currentAltTexture != num ? (oldAltTexture != num ? 0 : (currentAltTexture == 0 ? 1 : 0)) : 1) == 0)
      return;
    for (int index = 0; index < 20; ++index)
    {
