  private void CheckDialogue()
  {
    if (Main.netMode == 2)
      return;
    if (((long) Main.GameUpdateCount + (long) this.whoAmI) % 10L == 0L)
    {
      ConditionalDialogue.TryGetPendingDialogue(this, out this.nextDialogue);
    }
    else
    {
