  private void UpdateNetworkCode(int i)
  {
    this.whoAmI = i;
    if (!this.active)
      this.netUpdate = true;
    if (Main.netMode != 2)
      return;
    if (this.townNPC)
      this.netSpam = Math.Min(this.netSpam, this.netSpamTicksPerPacket);
    if (!this.active)
      this.netSpam = 0;
    if (this.netUpdate || this.netUpdatePendingSpamCooldown || this.netUpdatePendingFullSpamCooldown && this.netSpam == 0)
    {
      int num = this.boss ? this.netSpamTicksPerPacketForBosses : this.netSpamTicksPerPacket;
      if (this.netSpam <= this.netSpamPacketLimit * num)
      {
        this.netSpam += num;
        NetMessage.SendData(23, number: this.whoAmI);
      }
      else
        this.netUpdatePendingSpamCooldown = true;
    }
    if (this.netSpam > 0)
      --this.netSpam;
    this.RecheckSectionsForSkippedUpdates();
    this.StreamUpdatesToNearbyPlayers();
    if (!this.active || !this.townNPC || NPC.TypeToDefaultHeadIndex(this.type) <= 0)
      return;
    if (this.homeless != this.oldHomeless || this.homeTileX != this.oldHomeTileX || this.homeTileY != this.oldHomeTileY)
      NetMessage.SendData(60, number: this.whoAmI, number2: (float) this.homeTileX, number3: (float) this.homeTileY, number4: (float) WorldGen.TownManager.GetHouseholdStatus(this));
    this.oldHomeless = this.homeless;
    this.oldHomeTileX = this.homeTileX;
    this.oldHomeTileY = this.homeTileY;
  }

  private void StreamUpdatesToNearbyPlayers()
  {
    if (Main.npcStreamSpeed <= 0 || this.townNPC || !NPCID.Sets.UsesMultiplayerProximitySyncing[this.type] || (double) Math.Abs(this.velocity.X) + (double) Math.Abs(this.velocity.Y) <= 0.5)
      return;
    ++this.netStream;
    if (this.netStream < Main.npcStreamSpeed)
      return;
    this.netStream = 0;
    for (int remoteClient = 0; remoteClient < (int) byte.MaxValue; ++remoteClient)
    {
      if (Main.player[remoteClient].active)
      {
        float num1 = this.Center.Distance(Main.player[remoteClient].ReportedCameraPosition);
        int num2 = this.boss ? 8 : ((double) num1 < 250.0 ? 8 : ((double) num1 < 500.0 ? 4 : ((double) num1 < 1000.0 ? 2 : ((double) num1 < 1500.0 ? 1 : 0))));
        this.playerNetSyncState[remoteClient].streamCounter += (byte) num2;
        if (this.playerNetSyncState[remoteClient].streamCounter >= (byte) 8)
          NetMessage.SendData(23, remoteClient, number: this.whoAmI);
      }
    }
  }

  public Point NetSectionCoordinates
  {
    get
    {
      return new Point(Netplay.GetSectionX((int) this.position.X >> 4), Netplay.GetSectionY((int) this.position.Y >> 4));
    }
  }

  private void RecheckSectionsForSkippedUpdates()
  {
    NPC.PlayerNetSyncState[] playerNetSyncState = this.playerNetSyncState;
    for (int remoteClient = 0; remoteClient < playerNetSyncState.Length; ++remoteClient)
    {
      if (playerNetSyncState[remoteClient].skippedSyncs > (byte) 0 && Main.player[remoteClient].active && Netplay.Clients[remoteClient].IsSectionActive(this.NetSectionCoordinates))
        NetMessage.SendData(23, remoteClient, number: this.whoAmI);
    }
  }

