  public bool AppearsFriendlyToHunterPotion()
  {
    bool hunterPotion = this.friendly || this.catchItem > (short) 0 || this.damage == 0 && this.lifeMax == 5;
    bool? nullable = NPCID.Sets.HunterPotionFriendlyOverride[this.type];
    if (nullable.HasValue)
