  public Color GetNPCColorTintedByBuffs(Color npcColor)
  {
    if (!this.canDisplayBuffs)
      return npcColor;
    float R = 1f;
    float G1 = 1f;
    float B1 = 1f;
    float A = 1f;
    if (this.brokenArmor)
    {
      R *= 0.75f;
      G1 *= 0.75f;
      B1 *= 0.75f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.poisoned)
    {
      R *= 0.65f;
      B1 *= 0.75f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.venom)
    {
      G1 *= 0.45f;
      R *= 0.75f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.bleeding || this.hemorrhage)
    {
      G1 *= 0.85f;
      B1 *= 0.85f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.midas)
    {
      B1 *= 0.3f;
      R *= 0.85f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.betsysCurse)
    {
      R *= 0.8f;
      G1 *= 0.6f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.oiled)
    {
      R *= 0.4f;
      G1 *= 0.4f;
      B1 *= 0.4f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.stinky)
    {
      R *= 0.7f;
      B1 *= 0.55f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.drippingSlime)
    {
      R *= 0.8f;
      G1 *= 0.8f;
      npcColor = NPC.buffColor(npcColor, R, G1, B1, A);
    }
    if (this.drippingSparkleSlime)
    {
      float B2 = B1 * 0.85f;
      float G2 = G1 * 0.75f;
      npcColor = NPC.buffColor(npcColor, R, G2, B2, A);
    }
    if (this.ichor)
      npcColor = new Color((int) byte.MaxValue, (int) byte.MaxValue, 0, (int) byte.MaxValue);
    if (this.CanApplyHunterPotionEffects() && this.lifeMax > 1)
    {
      byte num1;
      byte num2;
      byte num3;
      if (this.AppearsFriendlyToHunterPotion())
      {
        num1 = (byte) 50;
        num2 = byte.MaxValue;
        num3 = (byte) 50;
      }
      else
      {
        num1 = byte.MaxValue;
        num2 = (byte) 50;
        num3 = (byte) 50;
      }
      if ((int) npcColor.R < (int) num1)
        npcColor.R = num1;
      if ((int) npcColor.G < (int) num2)
        npcColor.G = num2;
      if ((int) npcColor.B < (int) num3)
        npcColor.B = num3;
    }
    return npcColor;
  }

