  private void ApplyEelWhipDoT()
  {
    float num1 = 60f;
    int num2 = 0;
    int num3 = 3;
    int num4 = 50;
    int num5 = 50;
    if ((double) ++this.electricEelCounter < (double) num1)
      return;
    this.electricEelCounter = 0;
    int num6 = 0;
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      Player player = Main.player[index];
      if (player.active && player.TagEffectState.Type == 5478 && player.TagEffectState.IsNPCTagged(this.whoAmI))
        ++num6;
    }
    if (num6 == 0)
      return;
    int num7 = 600;
    if (!this.immortal)
    {
      for (int index = 0; index < Main.maxNPCs && num2 < num3; ++index)
      {
        if (index != this.whoAmI)
        {
          NPC npc = Main.npc[index];
          if (npc.active && npc.markedByEelWhip && !npc.immortal && (this.realLife == -1 || this.realLife != npc.realLife) && (double) this.Distance(npc.Hitbox.ClosestPointInRect(this.Center)) <= (double) num7)
          {
            ++num2;
            Vector2 vector2_1 = Main.rand.NextVector2FromRectangle(this.Hitbox);
            Vector2 vector2_2 = Main.rand.NextVector2FromRectangle(npc.Hitbox);
            ParticleOrchestrator.RequestParticleSpawn(true, ParticleOrchestraType.BlueLightningSmallLong, new ParticleOrchestraSettings()
            {
              PositionInWorld = vector2_1,
              MovementVector = vector2_2 - vector2_1
            });
          }
        }
      }
    }
    SoundEngine.PlaySound(this.HitSound, this.Center);
    if (Main.netMode == 1)
      return;
    int num8 = (num4 + num2 * num5) * num6;
    this.GetHurtByDebuff(num8);
    if (Main.netMode != 2)
      return;
    NetMessage.TrySendData(153, number: this.whoAmI, number2: (float) num8);
  }

  public void GetHurtByDebuff(int amount)
  {
    if (Main.netMode != 1)
      NPCDamageTracker.AddDamage(this, (int) byte.MaxValue, amount);
    int number = this.whoAmI;
    if (this.realLife >= 0)
      number = this.realLife;
    if (!Main.npc[number].immortal)
      Main.npc[number].life -= amount;
    CombatText.NewText(new Microsoft.Xna.Framework.Rectangle((int) this.position.X, (int) this.position.Y, this.width, this.height), CombatText.LifeRegenNegative, amount, dot: true);
    if (Main.npc[number].life > 0 || Main.npc[number].immortal)
      return;
    Main.npc[number].life = 1;
    if (Main.netMode == 1)
      return;
    Main.npc[number].StrikeNPCNoInteraction(9999, 0.0f, 0);
    if (Main.netMode != 2)
      return;
    NetMessage.SendData(28, number: number, number2: 9999f);
  }

  private void UpdateNPC_BuffClearExpiredBuffs()
  {
    if (Main.netMode == 1)
      return;
    bool flag = false;
    for (int buffIndex = 0; buffIndex < NPC.maxBuffs; ++buffIndex)
    {
      if (this.buffType[buffIndex] > 0 && this.buffTime[buffIndex] <= 0)
      {
        this.DelBuff(buffIndex, true);
        flag = true;
      }
    }
    if (!flag || Main.netMode != 2)
      return;
    NetMessage.SendData(54, number: this.whoAmI);
  }

  private void UpdateNPC_BloodMoonTransformations()
  {
    if (Main.netMode == 1 || !Main.bloodMoon)
      return;
    bool flag = false;
    if ((double) this.value == 0.0)
      flag = true;
    this.AttemptToConvertNPCToEvil(WorldGen.crimson);
    if (!flag)
      return;
    this.value = 0.0f;
  }

  public void AttemptToConvertNPCToEvil(bool crimson)
  {
    if (this.type == 46 || this.type == 303 || this.type == 337 || this.type == 443 || this.type == 540)
    {
      if (crimson)
        this.Transform(464);
      else
        this.Transform(47);
    }
    else if (this.type == 55 || this.type == 230 || this.type == 592 || this.type == 593)
    {
      if (crimson)
        this.Transform(465);
      else
        this.Transform(57);
    }
    else
    {
      if (this.type != 148 && this.type != 149)
        return;
      if (crimson)
        this.Transform(470);
      else
        this.Transform(168);
    }
  }

  public void UpdateNPC_BuffSetFlags(bool lowerBuffTime = true)
  {
    for (int buffIndex = 0; buffIndex < NPC.maxBuffs; ++buffIndex)
    {
      if (this.buffType[buffIndex] > 0 && this.buffTime[buffIndex] > 0)
      {
        if (lowerBuffTime)
          --this.buffTime[buffIndex];
        if (this.buffType[buffIndex] == 20)
          this.poisoned = true;
        if (this.buffType[buffIndex] == 25)
          this.tipsy = true;
        if (this.buffType[buffIndex] == 30)
          this.bleeding = true;
        if (this.buffType[buffIndex] == 375)
          this.hemorrhage = true;
        if (this.buffType[buffIndex] == 70)
          this.venom = true;
        if (this.buffType[buffIndex] == 24)
        {
          if (this.type == 1 && (double) this.ai[1] == 9.0)
            this.buffTime[buffIndex] = 60;
          this.onFire = true;
        }
        if (this.buffType[buffIndex] == 72)
          this.midas = true;
        if (this.buffType[buffIndex] == 69)
          this.ichor = true;
        if (this.buffType[buffIndex] == 36)
          this.brokenArmor = true;
        if (this.buffType[buffIndex] == 31 /*0x1F*/)
          this.confused = true;
        if (this.buffType[buffIndex] == 39)
          this.onFire2 = true;
