  private void TryRemovingWaterPerishableEffects(bool isInLava)
  {
    if ((this.onFire || this.onFire3) && !isInLava && Main.netMode != 1)
    {
      for (int buffIndex = 0; buffIndex < NPC.maxBuffs; ++buffIndex)
      {
        switch (this.buffType[buffIndex])
        {
          case 24:
          case 323:
            this.DelBuff(buffIndex);
            break;
        }
      }
    }
    if (!this.stinky || Main.netMode == 1)
      return;
    for (int buffIndex = 0; buffIndex < NPC.maxBuffs; ++buffIndex)
    {
      if (this.buffType[buffIndex] == 120)
        this.DelBuff(buffIndex);
    }
  }

  private void TryAddingRepeatedBuff(
    int buffId,
    int timeToGive,
    int lowThresholdUndeathToAllowBuff = 10)
  {
    if (this.buffImmune[buffId])
      return;
    int buffIndex = this.FindBuffIndex(buffId);
    if (buffIndex != -1 && this.buffTime[buffIndex] > lowThresholdUndeathToAllowBuff)
      return;
    this.AddBuff(buffId, timeToGive);
  }

