    public Spawner()
    {
      this.numberOfActivePlayers = Main.CurrentFrameFlags.ActivePlayersCount;
      float num1 = 0.0f;
      for (int index = 0; index < Main.maxNPCs; ++index)
      {
        if (Main.npc[index].active)
        {
          switch (Main.npc[index].type)
          {
            case 315:
            case 325:
            case 327:
            case 328:
            case 344:
            case 345:
            case 346:
              num1 += Main.npc[index].npcSlots;
              continue;
            default:
              continue;
          }
        }
      }
      int num2 = (int) ((double) NPC.defaultMaxSpawns * (2.0 + 0.30000001192092896 * (double) this.numberOfActivePlayers));
      this.reachedInvasionBossCap = (double) num1 >= (double) (this.numberOfActivePlayers * num2);
    }

    public void SpawnNPC()
    {
      for (int index = 0; index < (int) byte.MaxValue; ++index)
      {
        Player player = Main.player[index];
        if (NPC.Spawner.CanSpawnEnemiesNear(player))
        {
          if (Main.slimeRain)
            NPC.Spawner.SlimeRainSpawns(player);
          if (this.TrySpawnAnNPC(player))
            break;
        }
      }
    }

    private bool TrySpawnAnNPC(Player player)
    {
      this.SetSpawnFlags(player);
      int spawnRate;
      int maxSpawns;
      this.GetSpawnRate(player, out spawnRate, out maxSpawns);
      int spawnTileX;
      int spawnTileY;
      bool xRange;
      if ((double) player.nearbyActiveNPCs >= (double) maxSpawns || Main.rand.Next(spawnRate) != 0 || !this.FindSpawnTile(player, out spawnTileX, out spawnTileY, out xRange) || !NPC.Spawner.CheckNotSpawningOnScreen(spawnTileX, spawnTileY))
        return false;
      int spawnTileType = 0;
      int spawnWallType = 0;
      NPC.Spawner.GetProperGroundSpawnTileTypeAndWallType(spawnTileX, spawnTileY, out spawnTileType, out spawnWallType);
      if (!this.PostCheckChosenSpawnTile(spawnTileX, spawnTileY, spawnTileType, spawnWallType))
        return false;
      this.SetSpawnFlagsForChosenTile(spawnTileX, spawnTileY, spawnTileType, spawnWallType);
      if (this.dualDungeonsSpawnRules && this.ZoneDungeon)
      {
        if (!player.ZoneDungeon)
        {
          this.ZoneDungeon = false;
        }
        else
        {
          Tile tile = Main.tile[this.pX, this.pY];
          if (tile == null || !Main.wallDungeon[(int) tile.wall])
            this.ZoneDungeon = false;
        }
      }
      this.SpawnAnNPC(spawnTileX, spawnTileY, spawnTileType, xRange, player.whoAmI);
      if (Main.netMode == 2)
        NPC.Spawner.SyncNewlySpawnedNPCs();
      return true;
    }

    public static bool CanSpawnEnemiesNear(Player player)
    {
      if (!player.active || player.dead)
        return false;
      if (Main.IsJourneyMode)
      {
        CreativePowers.SpawnRateSliderPerPlayerPower power = CreativePowerManager.Instance.GetPower<CreativePowers.SpawnRateSliderPerPlayerPower>();
        if (power != null && power.GetIsUnlocked() && power.GetShouldDisableSpawnsFor(player.whoAmI))
          return false;
      }
      return !player.isNearNPC(398, (float) NPC.MoonLordFightingDistance);
    }

    private void SetSpawnFlags(Player player)
    {
      this.pX = (int) player.Center.X / 16 /*0x10*/;
      this.pY = (int) player.Center.Y / 16 /*0x10*/;
      this.luck = player.luck;
      this.dayTime = Main.dayTime;
      this.raining = Main.raining;
      this.skyMob = false;
      this.spawnFriendly = false;
      this.ignoreSafeWalls = false;
      this.waterTile = false;
      this.nearGranite = false;
      this.nearMarble = false;
      this.spawnSpider = false;
      this.spawnUndergroundDesert = false;
      this.hardDungeon = NPC.downedPlantBoss && Main.hardMode;
      this.ZoneCorrupt = player.ZoneCorrupt;
      this.ZoneCrimson = player.ZoneCrimson;
      this.ZoneHallow = player.ZoneHallow;
      this.ZoneJungle = player.ZoneJungle;
      this.ZoneSnow = player.ZoneSnow;
      this.ZoneGlowshroom = player.ZoneGlowshroom;
      this.ZoneMeteor = player.ZoneMeteor;
      this.ZoneGraveyard = player.ZoneGraveyard;
      this.ZoneDungeon = player.ZoneDungeon;
      this.ZoneLihzhardTemple = player.ZoneLihzhardTemple;
      this.ZoneSandstorm = player.ZoneSandstorm;
      this.ZoneTowerSolar = player.ZoneTowerSolar;
      this.ZoneTowerVortex = player.ZoneTowerVortex;
      this.ZoneTowerNebula = player.ZoneTowerNebula;
      this.ZoneTowerStardust = player.ZoneTowerStardust;
      this.ZoneOldOneArmy = player.ZoneOldOneArmy;
      this.ZoneWaterCandle = player.ZoneWaterCandle;
      this.ZonePeaceCandle = player.ZonePeaceCandle;
      this.ZoneShadowCandle = player.ZoneShadowCandle;
      this.dualDungeonsSpawnRules = Main.dualDungeonsSeed;
      this.inDualDungeon = this.dualDungeonsSpawnRules && player.insideUnbreakableWalls;
      this.tresspassingDualDungeon = this.inDualDungeon && DangerousDungeonCurse.GetProgressPlayerCanSafelyMatch() < DangerousDungeonCurse.GetProgressPlayerNeedsToMatch(player);
      this.invaders = NPC.Spawner.ShouldSpawnInvasionEnemies(player.position);
      if (this.ZoneTowerSolar || this.ZoneTowerNebula || this.ZoneTowerVortex || this.ZoneTowerStardust)
      {
        this.invaders = true;
        this.ignoreSafeWalls = true;
      }
      this.townNPCs = player.townNPCs;
      this.noWorms = WorldGen.InWorld(this.pX, this.pY) && Main.wallHouse[(int) Main.tile[this.pX, this.pY].wall];
      this.noGroundWorms = player.afkCounter >= Player.AFKTimeNeededForNoWormSpawns;
      this.skyBehindPlayer = Main.wallLight[(int) Main.tile[this.pX, this.pY].wall] || Main.tile[this.pX, this.pY].wall == (ushort) 73;
      this.livingTree = Main.tile[this.pX, this.pY].wall == (ushort) 244;
      this.inRemixStartingArea = Main.remixWorld && (double) player.Center.X / 16.0 > (double) Main.maxTilesX * 0.39 + 50.0 && (double) player.Center.X / 16.0 < (double) Main.maxTilesX * 0.61;
      this.offensiveToTim = (player.armor[1].type == 4256 || player.armor[1].type >= 1282 && player.armor[1].type <= 1287) && player.armor[0].type != 238;
      this.playerHasStartingHealth = player.statLifeMax <= 100;
      if (!this.ZoneShadowCandle)
        return;
      this.noWorms = false;
      this.noGroundWorms = false;
      this.townNPCs = 0;
    }

    private void SetSpawnFlagsForChosenTile_ForDualDungeon(
      int spawnTileX,
