    public static bool ShouldSpawnInvasionEnemies(Vector2 position)
    {
      if (Main.invasionType <= 0 || Main.invasionDelay != 0 || Main.invasionSize <= 0 || (double) position.Y >= Main.worldSurface * 16.0 + (double) NPC.sHeight && (double) Main.spawnTileY <= Main.worldSurface)
        return false;
      int num = 3000;
      if ((double) position.X > Main.invasionX * 16.0 - (double) num && (double) position.X < Main.invasionX * 16.0 + (double) num)
        return true;
      if (Main.invasionX >= (double) (Main.maxTilesX / 2 - 5) && Main.invasionX <= (double) (Main.maxTilesX / 2 + 5))
      {
        for (int index = 0; index < Main.maxNPCs; ++index)
        {
          if (Main.npc[index].townNPC && (double) Math.Abs(position.X - Main.npc[index].Center.X) < (double) num)
          {
            if (Main.rand.Next(3) != 0)
              return true;
            break;
          }
        }
      }
      return false;
    }

    private void GetSpawnRate(Player player, out int spawnRate, out int maxSpawns)
    {
      spawnRate = NPC.defaultSpawnRate;
      maxSpawns = NPC.defaultMaxSpawns;
      if (Main.hardMode)
      {
        spawnRate = (int) ((double) NPC.defaultSpawnRate * 0.9);
        maxSpawns = NPC.defaultMaxSpawns + 1;
      }
      if ((double) player.position.Y > (double) (Main.UnderworldLayer * 16 /*0x10*/))
        maxSpawns = (int) ((double) maxSpawns * 2.0);
      else if ((double) player.position.Y > Main.rockLayer * 16.0 + (double) NPC.sHeight)
      {
        if (Main.remixWorld)
        {
          if (Main.hardMode)
          {
            spawnRate = (int) ((double) spawnRate * 0.45);
            maxSpawns = (int) ((double) maxSpawns * 1.7999999523162842);
          }
          else
          {
            spawnRate = (int) ((double) spawnRate * 0.5);
            maxSpawns = (int) ((double) maxSpawns * 1.7000000476837158);
          }
        }
        else
        {
          spawnRate = (int) ((double) spawnRate * 0.4);
          maxSpawns = (int) ((double) maxSpawns * 1.8999999761581421);
        }
      }
      else if ((double) player.position.Y > Main.worldSurface * 16.0 + (double) NPC.sHeight)
      {
        if (Main.remixWorld)
        {
          spawnRate = (int) ((double) spawnRate * 0.4);
          maxSpawns = (int) ((double) maxSpawns * 1.8999999761581421);
        }
        else if (Main.hardMode)
        {
          spawnRate = (int) ((double) spawnRate * 0.45);
          maxSpawns = (int) ((double) maxSpawns * 1.7999999523162842);
        }
        else
        {
          spawnRate = (int) ((double) spawnRate * 0.5);
          maxSpawns = (int) ((double) maxSpawns * 1.7000000476837158);
        }
      }
      else if (Main.remixWorld)
      {
        if (!Main.dayTime)
        {
          spawnRate = (int) ((double) spawnRate * 0.6);
          maxSpawns = (int) ((double) maxSpawns * 1.2999999523162842);
        }
      }
      else if (!Main.dayTime)
      {
        spawnRate = (int) ((double) spawnRate * 0.6);
        maxSpawns = (int) ((double) maxSpawns * 1.2999999523162842);
        if (Main.bloodMoon)
        {
          spawnRate = (int) ((double) spawnRate * 0.3);
          maxSpawns = (int) ((double) maxSpawns * 1.7999999523162842);
        }
        if ((Main.pumpkinMoon || Main.snowMoon) && (double) player.position.Y < Main.worldSurface * 16.0)
        {
          spawnRate = (int) ((double) spawnRate * 0.2);
          maxSpawns *= 2;
        }
      }
      else if (Main.dayTime && Main.eclipse)
      {
        spawnRate = (int) ((double) spawnRate * 0.2);
        maxSpawns = (int) ((double) maxSpawns * 1.8999999761581421);
      }
      if (Main.remixWorld)
      {
        if (!Main.dayTime)
        {
          if (Main.bloodMoon)
          {
            spawnRate = (int) ((double) spawnRate * 0.3);
            maxSpawns = (int) ((double) maxSpawns * 1.7999999523162842);
            if ((double) player.position.Y > Main.rockLayer * 16.0 + (double) NPC.sHeight)
              spawnRate = (int) ((double) spawnRate * 0.6);
          }
          if (Main.pumpkinMoon || Main.snowMoon)
          {
            spawnRate = (int) ((double) spawnRate * 0.2);
            maxSpawns *= 2;
            if ((double) player.position.Y > Main.rockLayer * 16.0 + (double) NPC.sHeight)
              spawnRate = (int) ((double) spawnRate * 0.6);
          }
        }
        else if (Main.dayTime && Main.eclipse)
        {
          spawnRate = (int) ((double) spawnRate * 0.2);
          maxSpawns = (int) ((double) maxSpawns * 1.8999999761581421);
        }
      }
      if (this.ZoneSnow && (double) player.position.Y / 16.0 < Main.worldSurface)
      {
        maxSpawns = (int) ((double) maxSpawns + (double) maxSpawns * (double) Main.cloudAlpha);
        spawnRate = (int) ((double) spawnRate * (1.0 - (double) Main.cloudAlpha + 1.0) / 2.0);
      }
      if (Main.drunkWorld && Main.tile[this.pX, this.pY].wall == (ushort) 86)
      {
        spawnRate = (int) ((double) spawnRate * 0.3);
        maxSpawns = (int) ((double) maxSpawns * 1.7999999523162842);
      }
