    public bool FindSpawnTile(
      Player player,
      out int spawnTileX,
      out int spawnTileY,
      out bool xRange)
    {
      Microsoft.Xna.Framework.Rectangle spawnArea;
      Microsoft.Xna.Framework.Rectangle safeArea;
      NPC.Spawner.GetSpawnArea(player, out spawnArea, out safeArea);
      for (int index1 = 0; index1 < 50; ++index1)
      {
        int index2 = Main.rand.Next(spawnArea.Left, spawnArea.Right);
        int index3 = Main.rand.Next(spawnArea.Top, spawnArea.Bottom);
        if ((!Main.tile[index2, index3].nactive() || !Main.tileSolid[(int) Main.tile[index2, index3].type]) && (this.ignoreSafeWalls || !Main.wallHouse[(int) Main.tile[index2, index3].wall]))
        {
