              ++index3;
            if (index3 >= spawnArea.Bottom)
              continue;
          }
          spawnTileX = index2;
          spawnTileY = index3;
          if (!safeArea.Contains(spawnTileX, spawnTileY) && NPC.Spawner.HasTileSpawnSpace(spawnTileX, spawnTileY))
          {
            xRange = spawnTileX >= safeArea.Left && spawnTileX < safeArea.Right;
            return true;
          }
        }
      }
      spawnTileX = 0;
      spawnTileY = 0;
      xRange = false;
      return false;
    }

