    public NPC SpawnNPC(
      int X,
      int Y,
      int Type,
      int Start = 0,
      float ai0 = 0.0f,
      float ai1 = 0.0f,
      float ai2 = 0.0f,
      float ai3 = 0.0f,
      int Target = 255 /*0xFF*/)
    {
      if (NPCID.FromNetId(Type) == 1)
      {
        if (this.RollLuck(180) == 0)
          Type = -4;
        if (Main.tenthAnniversaryWorld && this.RollLuck(180) == 0)
          Type = 667;
      }
      if (Target == (int) byte.MaxValue)
        Target = this.defaultTarget;
      int index = NPC.NewNPC(NPC.GetSpawnSourceForNaturalSpawn(), X, Y, Type, Start, ai0, ai1, ai2, ai3, Target);
      NPC npc = Main.npc[index];
      if (Main.dualDungeonsSeed && (double) Y > Main.worldSurface * 16.0 && Y < Main.UnderworldLayer * 16 /*0x10*/)
        ParticleOrchestrator.BroadcastOrRequestParticleSpawn(ParticleOrchestraType.InScreenDungeonSpawn, new ParticleOrchestraSettings()
        {
          PositionInWorld = new Vector2((float) X, (float) Y),
          MovementVector = new Vector2((float) npc.width, (float) npc.height),
          UniqueInfoPiece = Type
        });
      return npc;
    }

    private static void SyncNewlySpawnedNPCs()
    {
      for (int number = 0; number < Main.maxNPCs; ++number)
      {
        NPC npc = Main.npc[number];
        if (npc.active && npc.spawnNeedsSyncing)
          NetMessage.SendData(23, number: number);
      }
    }

