    public static bool CanSpawnInTiles(Microsoft.Xna.Framework.Rectangle tileRect)
    {
      for (int left = tileRect.Left; left < tileRect.Right; ++left)
      {
        for (int top = tileRect.Top; top < tileRect.Bottom; ++top)
        {
          if (!NPC.Spawner.CanSpawnInTile(left, top))
