    public static int GetBasicSlimeToSpawn(bool surface, int tileType, int spawnDist)
    {
      short basicSlimeToSpawn = 1;
      if (surface)
      {
        switch (tileType)
        {
          case 60:
            basicSlimeToSpawn = (short) -10;
            break;
          case 147:
          case 161:
            basicSlimeToSpawn = (short) 147;
            break;
          default:
            if (Main.halloween && NPC.Spawner.GetBasicSlimeToSpawn_ChanceToBeHolidaySlime())
            {
              basicSlimeToSpawn = (short) 302;
              break;
            }
            if (Main.xMas && NPC.Spawner.GetBasicSlimeToSpawn_ChanceToBeHolidaySlime())
            {
              basicSlimeToSpawn = (short) Main.rand.Next(333, 337);
              break;
            }
            if (Main.rand.Next(3) == 0 || spawnDist < 200 && !Main.expertMode)
            {
              basicSlimeToSpawn = (short) -3;
              break;
            }
            if (Main.rand.Next(10) == 0 && (spawnDist > 400 || Main.expertMode))
            {
              basicSlimeToSpawn = (short) -7;
              break;
            }
            break;
        }
      }
      else
        basicSlimeToSpawn = Main.rand.Next(5) != 0 ? (Main.rand.Next(2) != 0 ? (short) -8 : (short) 1) : (short) -9;
      return (int) basicSlimeToSpawn;
    }

