    public static void GetProperGroundSpawnTileTypeAndWallType(
      int x,
      int y,
      out int spawnTileType,
      out int spawnWallType)
    {
      spawnTileType = (int) Main.tile[x, y].type;
      spawnWallType = y > 0 ? (int) Main.tile[x, y - 1].wall : 0;
      if (TileID.Sets.UsesADifferentTileTypeForNPCSpawning[spawnTileType] && WorldGen.InWorld(x, y + 1) && WorldGen.SolidTile3(x, y + 1))
      {
        Tile tile = Main.tile[x, y];
        spawnTileType = (int) Main.tile[x, y + 1].type;
        spawnWallType = (int) tile.wall;
      }
      if (NPC.Spawner.IsValidSpawningGroundTile(x, y))
        return;
      for (int y1 = y + 1; y1 < y + 30; ++y1)
      {
        if (NPC.Spawner.IsValidSpawningGroundTile(x, y1))
        {
          Tile tile = Main.tile[x, y1 - 1];
          spawnTileType = (int) Main.tile[x, y1].type;
          spawnWallType = (int) tile.wall;
          break;
        }
      }
    }

    public static bool IsValidSpawningGroundTile(int x, int y)
    {
