      return tile.nactive() && Main.tileSolid[(int) tile.type] && !Main.tileSolidTop[(int) tile.type];
    }

    public static void SlimeRainSpawns(Player player)
    {
      int y = Main.MaxWorldViewSize.Y;
      int x = Main.MaxWorldViewSize.X;
      float num1 = 15f;
      if ((double) player.position.Y > Main.worldSurface * 16.0 + (double) (y / 2) || (double) player.nearbyActiveNPCs > (double) num1)
        return;
      int maxValue1 = 45 + (int) (450.0 * (double) (player.nearbyActiveNPCs / num1));
      if (Main.expertMode)
        maxValue1 = (int) ((double) maxValue1 * 0.85);
      if (Main.IsJourneyMode)
      {
        CreativePowers.SpawnRateSliderPerPlayerPower power = CreativePowerManager.Instance.GetPower<CreativePowers.SpawnRateSliderPerPlayerPower>();
        float num2;
        if (power != null && power.GetIsUnlocked() && power.GetRemappedSliderValueFor(player.whoAmI, out num2))
          maxValue1 = (int) ((double) maxValue1 / (double) num2);
      }
      if (Main.rand.Next(maxValue1) != 0)
        return;
      int minValue1 = (int) ((double) player.Center.X - (double) x);
      int maxValue2 = minValue1 + x * 2;
      int minValue2 = (int) ((double) player.Center.Y - (double) y * 1.5);
      int maxValue3 = (int) ((double) player.Center.Y - (double) y * 0.75);
      int num3 = Main.rand.Next(minValue1, maxValue2);
      int num4 = Main.rand.Next(minValue2, maxValue3);
      int index1 = num3 / 16 /*0x10*/;
      int index2 = num4 / 16 /*0x10*/;
      if (index1 < 10 || index1 > Main.maxTilesX + 10 || (double) index2 < Main.worldSurface * 0.3 || (double) index2 > Main.worldSurface || Collision.SolidTiles(index1 - 3, index1 + 3, index2 - 5, index2 + 2) || Main.wallHouse[(int) Main.tile[index1, index2].wall])
        return;
      int Type = 1;
      if (Main.rand.Next(200) == 0)
        Type = -4;
      else if (Main.expertMode)
      {
        if (Main.rand.Next(7) == 0)
          Type = -7;
        else if (Main.rand.Next(3) == 0)
          Type = -3;
      }
      else if (Main.rand.Next(10) == 0)
        Type = -7;
      else if (Main.rand.Next(5) < 2)
        Type = -3;
      NPC.NewNPC(NPC.GetSpawnSourceForNaturalSpawn(), index1 * 16 /*0x10*/ + 8, index2 * 16 /*0x10*/, Type);
    }

    public static void SpawnFaelings(Player player)
