      for (int index1 = 0; index1 < num1; ++index1)
      {
        int num2 = 1000;
        for (int index2 = 0; index2 < num2; ++index2)
        {
          int index3 = Main.rand.Next(spawnArea.Left, spawnArea.Right);
          int index4 = Main.rand.Next(spawnArea.Top, spawnArea.Bottom);
          if (Main.tile[index3, index4].liquid > (byte) 0 && Main.tile[index3, index4].shimmer())
          {
            for (; Main.tile[index3, index4].liquid > (byte) 0; --index4)
